      (if Z.leb ((Z.add (off) (len))) (bytes.(StatelessInputSliceFields_len)) then
         returnM ((InputCalldata
                     (@existT _ _ _ (@existT _ _ _ (stateless_input_sub_slice (bytes) (off) (len))))))
       else assert_exp' false "calldata sub-slice bounds" >>= fun _ => exit tt)
       : M (CalldataSlice)
   | MemoryCalldata (@existT _ _ syn_len (@existT _ _ syn_off bytes)) =>
      (if Z.leb ((Z.add (off) (len))) (bytes.(EvmMemorySliceFields_len)) then
         returnM ((MemoryCalldata
