Definition blob_schedule (target : Z) (maximum : Z) (denominator : Z)
(*((denominator =? 1) ||
  ((denominator =? 3338477) ||
    ((denominator =? 5007716) || ((denominator =? 8346193) || (denominator =? 11684671))))) &&
  ((target =? 0) && ((maximum =? 0) && (denominator =? 1)) ||
    ((target =? 3) && ((maximum =? 6) && (denominator =? 3338477)) ||
      ((target =? 6) && ((maximum =? 9) && (denominator =? 5007716)) ||
        ((target =? 10) && ((maximum =? 15) && (denominator =? 8346193)) ||
          (target =? 14) && ((maximum =? 21) && (denominator =? 11684671))))))*)
: BlobScheduleFields target maximum denominator :=
   {| BlobScheduleFields_target := target;
      BlobScheduleFields_max := maximum;
      BlobScheduleFields_base_fee_update_fraction := denominator |}.

Definition compute_profile_excess_blob_gas_limit
(fork : Z) (target : Z) (maximum : Z) (denominator : Z)
(*(0 <=? fork) &&
  ((fork <=? 16) &&
    (((denominator =? 1) ||
      ((denominator =? 3338477) ||
        ((denominator =? 5007716) || ((denominator =? 8346193) || (denominator =? 11684671))))) &&
      ((target =? 0) && ((maximum =? 0) && (denominator =? 1)) ||
        ((target =? 3) && ((maximum =? 6) && (denominator =? 3338477)) ||
          ((target =? 6) && ((maximum =? 9) && (denominator =? 5007716)) ||
            ((target =? 10) && ((maximum =? 15) && (denominator =? 8346193)) ||
              (target =? 14) && ((maximum =? 21) && (denominator =? 11684671))))))))*)
: profile_excess_blob_gas_limit fork target maximum denominator :=
   if Z.ltb (fork) (Cancun) then 0
   else Z.add ((Z.mul (256) (denominator))) ((Z.mul ((Z.sub (maximum) (target))) ((pow2 (17))))).

Definition pack_protocol_profile {fork : Z} {target : Z} {maximum : Z} {denominator : Z}
{code_limit : Z} {initcode_limit : Z} {transaction_total_gas_limit : Z}
{transaction_regular_gas_limit : Z} {transaction_blob_limit : Z} {refund_divisor : Z}
(profile : ProtocolProfileFields fork target maximum denominator code_limit initcode_limit transaction_total_gas_limit transaction_regular_gas_limit transaction_blob_limit refund_divisor)
(*(fork =? 5) &&
  ((target =? 0) &&
    ((maximum =? 0) &&
      ((denominator =? 1) &&
        ((code_limit =? 24576) &&
          ((initcode_limit =? 0) &&
            ((transaction_total_gas_limit =? (2 ^ 64 - 1)) &&
              ((transaction_regular_gas_limit =? (2 ^ 64 - 1)) &&
                ((transaction_blob_limit =? 0) && (refund_divisor =? 2))))))))) ||
  ((6 <=? fork) && (fork <=? 9) &&
    ((target =? 0) &&
      ((maximum =? 0) &&
        ((denominator =? 1) &&
          ((code_limit =? 24576) &&
            ((initcode_limit =? 0) &&
              ((transaction_total_gas_limit =? (2 ^ 64 - 1)) &&
                ((transaction_regular_gas_limit =? (2 ^ 64 - 1)) &&
                  ((transaction_blob_limit =? 0) && (refund_divisor =? 5))))))))) ||
    ((fork =? 10) &&
      ((target =? 0) &&
        ((maximum =? 0) &&
          ((denominator =? 1) &&
            ((code_limit =? 24576) &&
              ((initcode_limit =? 49152) &&
                ((transaction_total_gas_limit =? (2 ^ 64 - 1)) &&
                  ((transaction_regular_gas_limit =? (2 ^ 64 - 1)) &&
                    ((transaction_blob_limit =? 0) && (refund_divisor =? 5))))))))) ||
      ((fork =? 11) &&
        ((target =? 3) &&
          ((maximum =? 6) &&
            ((denominator =? 3338477) &&
              ((code_limit =? 24576) &&
                ((initcode_limit =? 49152) &&
                  ((transaction_total_gas_limit =? (2 ^ 64 - 1)) &&
                    ((transaction_regular_gas_limit =? (2 ^ 64 - 1)) &&
