Definition undefined_TxType '(tt : unit) : M (TxType) :=
   (internal_pick ([LegacyTx; AccessListTx; FeeMarketTx; BlobTx; SetCodeTx]))  : M (TxType).

Definition tx_envelope_type_forwards (arg_ : TxType) : mword 8 :=
   match arg_ with
   | LegacyTx => (Ox"00")
   | AccessListTx => (Ox"01")
   | FeeMarketTx => (Ox"02")
   | BlobTx => (Ox"03")
   | SetCodeTx => (Ox"04")
   end.

Definition tx_envelope_type_backwards (arg_ : mword 8) : M (TxType) :=
   let p0_ := arg_ in
   (if eq_vec (p0_) ((Ox"00")) then returnM (LegacyTx)
    else if eq_vec (p0_) ((Ox"01")) then returnM (AccessListTx)
    else if eq_vec (p0_) ((Ox"02")) then returnM (FeeMarketTx)
    else if eq_vec (p0_) ((Ox"03")) then returnM (BlobTx)
    else if eq_vec (p0_) ((Ox"04")) then returnM (SetCodeTx)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (TxType).

Definition tx_envelope_type_forwards_matches (arg_ : TxType) : bool :=
   match arg_ with
   | LegacyTx => true
   | AccessListTx => true
   | FeeMarketTx => true
   | BlobTx => true
   | SetCodeTx => true
   end.

Definition tx_envelope_type_backwards_matches (arg_ : mword 8) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) ((Ox"00")) then true
   else if eq_vec (p0_) ((Ox"01")) then true
   else if eq_vec (p0_) ((Ox"02")) then true
   else if eq_vec (p0_) ((Ox"03")) then true
   else if eq_vec (p0_) ((Ox"04")) then true
   else false.

