Definition tx_type_semantics (t : TxType) : TxTypeSemantics :=
   match t with
   | LegacyTx =>
      {| TxTypeSemantics_minimum_fork := (Build_Fork (Frontier));
         TxTypeSemantics_signature := LegacySignature;
         TxTypeSemantics_blob := false;
         TxTypeSemantics_set_code := false |}
   | AccessListTx =>
      {| TxTypeSemantics_minimum_fork := (Build_Fork (Berlin));
         TxTypeSemantics_signature := TypedSignature;
         TxTypeSemantics_blob := false;
         TxTypeSemantics_set_code := false |}
   | FeeMarketTx =>
      {| TxTypeSemantics_minimum_fork := (Build_Fork (London));
         TxTypeSemantics_signature := TypedSignature;
         TxTypeSemantics_blob := false;
         TxTypeSemantics_set_code := false |}
   | BlobTx =>
      {| TxTypeSemantics_minimum_fork := (Build_Fork (Cancun));
         TxTypeSemantics_signature := TypedSignature;
         TxTypeSemantics_blob := true;
         TxTypeSemantics_set_code := false |}
   | SetCodeTx =>
      {| TxTypeSemantics_minimum_fork := (Build_Fork (Prague));
         TxTypeSemantics_signature := TypedSignature;
         TxTypeSemantics_blob := false;
         TxTypeSemantics_set_code := true |}
   end.

