Definition logs_bloom_equal (a : vec (mword 8) 256) (b : vec (mword 8) 256) : bool :=
   let equal : bool := true in
   let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := 255 in
   (foreach_Z_up loop_i_lower loop_i_upper 1 equal
     (fun i '(equal) =>
       andb (equal) ((eq_vec ((vec_access_dec (a) (i))) ((vec_access_dec (b) (i))))))).

