Definition tx_validity_fields {limit : Z} {regular : Z} {intrinsic_execution : Z}
{intrinsic_state : Z} {calldata_floor : Z} {execution : Z} {state : Z}
(sender : vec (mword 8) 20) (nonce_before : account_nonce)
(gas : TransactionInitialGasFields limit regular intrinsic_execution intrinsic_state calldata_floor execution state)
(blob_fee : word) (gas_price : word) (priority_fee : word)
(*(0 <=? intrinsic_execution) &&
  ((0 <=? intrinsic_state) &&
    ((0 <=? calldata_floor) &&
      ((intrinsic_execution <=? regular) &&
        ((calldata_floor <=? regular) &&
          ((regular <=? limit) &&
            ((limit <=? (2 ^ 64 - 1)) &&
              ((0 <=? execution) &&
                ((0 <=? state) &&
                  (((execution + state + intrinsic_execution + intrinsic_state) =? limit) &&
                    (execution <=? (regular - intrinsic_execution)))))))))))*)
(*(0 <=? nonce_before) && (nonce_before <=? (2 ^ 64 - 1))*)
(*(0 <=? blob_fee) && (blob_fee <=? (2 ^ 256 - 1))*)
(*(0 <=? gas_price) && (gas_price <=? (2 ^ 256 - 1))*)
(*(0 <=? priority_fee) && (priority_fee <=? (2 ^ 256 - 1))*)
: TxValidityFields limit regular intrinsic_execution intrinsic_state calldata_floor execution state :=
