Definition fake_exponential_word {target : Z} {maximum : Z} {denominator0 : Z}
(schedule : BlobScheduleFields target maximum denominator0) (numerator : Z)
(*((denominator0 =? 1) ||
  ((denominator0 =? 3338477) ||
    ((denominator0 =? 5007716) || ((denominator0 =? 8346193) || (denominator0 =? 11684671))))) &&
  ((target =? 0) && ((maximum =? 0) && (denominator0 =? 1)) ||
    ((target =? 3) && ((maximum =? 6) && (denominator0 =? 3338477)) ||
      ((target =? 6) && ((maximum =? 9) && (denominator0 =? 5007716)) ||
        ((target =? 10) && ((maximum =? 15) && (denominator0 =? 8346193)) ||
          (target =? 14) && ((maximum =? 21) && (denominator0 =? 11684671)))))) &&
  ((0 <=? numerator) && (numerator <=? (256 * denominator0 + (maximum - target) * 2 ^ 17)))*)
: M (word) :=
   (let denominator : Z := schedule.(BlobScheduleFields_base_fee_update_fraction) in
   let scaled_limit : Z := Z.mul denominator0 ((pow2 (256))) in
   let term_index : Z := 1 in
   let output : Z := 0 in
   let numerator_accum : Z := denominator in
   (whileMT
     (numerator_accum, output, term_index)
     (fun '(numerator_accum, output, term_index) => Z.sub (scaled_limit) (output))
     (fun '(numerator_accum, output, term_index) => returnM ((Z.gtb (numerator_accum) (0))))
     (fun '(numerator_accum, output, term_index) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        let current_accum := numerator_accum in
        (if Z.leb (scaled_limit) (current_accum) return M ((Z * Z * Z)) then
           (fatal_error (NumericOverflow)) >>
           exit tt >> returnM ((numerator_accum, output, term_index))
         else
           let bounded_accum : Z := current_accum in
           let next_output := Z.add (output) (bounded_accum) in
           (if Z.leb (scaled_limit) (next_output) return M ((Z * Z * Z)) then
              (fatal_error (NumericOverflow)) >>
              exit tt >> returnM ((numerator_accum, output, term_index))
            else
              let output : Z := next_output in
              let numerator_accum : Z :=
                e_div ((Z.mul (bounded_accum) (numerator))) ((Z.mul denominator0 (term_index))) in
              let current_index := term_index in
              (if Z.ltb (current_index) (scaled_limit) then
                 let term_index : Z := Z.add (current_index) (1) in
                 returnM (term_index)
               else (fatal_error (NumericOverflow)) >> exit tt >> returnM (term_index)) >>= fun (term_index : Z) =>
              returnM ((numerator_accum, output, term_index)))
            : M ((Z * Z * Z)))
         : M ((Z * Z * Z)))
        : M ((Z * Z * Z)))) >>= fun '((numerator_accum, output, term_index)
   : (Z * Z * Z)) =>
   let price := e_div (output) denominator0 in
   returnM (((protocol_word (price)).(word_value)))) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

