             else if Z.leb (byte_len) ((e_div (available) (G_codedeposit))) then
               let cost : Z := Z.mul (G_codedeposit) (byte_len) in
               gas_charge (cost)
             else GAS_CHARGE_UNAFFORDABLE)).

