Definition pc_word (input : CalldataSlice) (start : Z) (byte_count : Z)
(*(0 <=? start) && (start <=? (2 ^ 32 - 1)) && ((0 <=? byte_count) && (byte_count <=? 32))*)
: M (word) :=
   (let value : Z := (ZERO_WORD).(word_value) in
   let start_offset := start in
   let count := byte_count in
   let input_length := (calldata_slice_length (input)).(source_length_value) in
   (let '(loop_byte_index_lower) := 0 in
   let '(loop_byte_index_upper) := 31 in
   (foreach_ZM_up loop_byte_index_lower loop_byte_index_upper 1 value
     (fun byte_index '(value) =>
       let offset : Z := byte_index in
       (if Z.ltb (offset) (count) return M (Z) then
          (if Z.ltb (start_offset) (input_length) return M (mword 8) then
             let remaining := Z.sub (input_length) (start_offset) in
             (if Z.ltb (offset) (remaining) return M (mword 8) then
                let cursor := Z.add (start_offset) (offset) in
                (calldata_slice_byte (input) (cursor))
                 : M (mword 8)
              else returnM ((Ox"00")))
              : M (mword 8)
           else returnM ((Ox"00"))) >>= fun next_byte =>
          let value : Z :=
            (word_add_word
               (((word_shift_left (Build_word ((value))) (Build_word_bit_count ((8)))).(word_value)))
               ((uint (next_byte)))).(word_value) in
          returnM (value)
        else returnM (value))
        : M (Z))))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition pc_word_after_declared_field
(input : CalldataSlice) (prefix : Z) (declared_length : word) (byte_count : Z)
(*(0 <=? prefix) && (prefix <=? (2 ^ 32 - 1)) && ((0 <=? byte_count) && (byte_count <=? 32))*)
(*(0 <=? declared_length) && (declared_length <=? (2 ^ 256 - 1))*)
: M (word) :=
   let declared_length := (declared_length).(word_value) in
   (let input_length := (calldata_slice_length (input)).(source_length_value) in
   let prefix_offset := prefix in
   (if Z.ltb (prefix_offset) (input_length) return M (Z) then
      let suffix_length := Z.sub (input_length) (prefix_offset) in
      (if Z.ltb (declared_length) (suffix_length) return M (Z) then
         let '(field_length) := declared_length  : Z in
         let start : Z := Z.add (prefix_offset) (field_length) in
         ((pc_word (input) (start) (byte_count)) >>= fun semanticResult =>
          returnM (semanticResult).(word_value))
          : M (Z)
       else returnM ((ZERO_WORD).(word_value)))
       : M (Z)
    else returnM ((ZERO_WORD).(word_value)))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition pc_blake2_rounds (input : CalldataSlice) : M (blake2_rounds) :=
