Definition modexp_gas (input : CalldataSlice) (available : Z) (*0 <=? available*) : M (GasCharge) :=
   catch_early_return
     (liftR (read_reg k_execution_profile) >>= fun '(@existT _ _ __execution_profile12 (@existT _ _ __execution_profile11 (@existT _ _ __execution_profile10 (@existT _ _ __execution_profile9 (@existT _ _ __execution_profile8 (@existT _ _ __execution_profile7 (@existT _ _ __execution_profile6 (@existT _ _ __execution_profile5 (@existT _ _ __execution_profile4 (@existT _ _ __execution_profile3 (@existT _ _ __execution_profile2 (@existT _ _ __execution_profile1 (@existT _ _ __execution_profile0 execution_profile))))))))))))) =>
     let profile := execution_profile.(ExecutionProfileFields_protocol) in
     liftR (((pc_word (input) (0) (32)) >>= fun semanticResult =>
             returnM (semanticResult).(word_value))) >>= fun bl_word =>
     liftR (((pc_word (input) (32) (32)) >>= fun semanticResult =>
             returnM (semanticResult).(word_value))) >>= fun el_word =>
     liftR (((pc_word (input) (64) (32)) >>= fun semanticResult =>
             returnM (semanticResult).(word_value))) >>= fun ml_word =>
     let bl : Z := bl_word in
     let el : Z := el_word in
     let ml : Z := ml_word in
     let osaka := Z.geb (profile.(ProtocolProfileFields_fork)) (Osaka) in
     (if andb (osaka)
           ((orb ((Z.gtb (bl) (1024))) ((orb ((Z.gtb (el) (1024))) ((Z.gtb (ml) (1024))))))) then
        returnR (GasCharge) (GAS_CHARGE_UNAFFORDABLE)
      else
        let minimum : Z := if osaka then 500 else 200 in
        (if Z.ltb (available) (minimum) then returnR (GasCharge) (GAS_CHARGE_UNAFFORDABLE)
         else if andb ((negb (osaka)))
                   ((andb ((word_is_zero (bl_word))) ((word_is_zero (ml_word))))) then
           returnR (GasCharge) ((gas_charge (200)))
         else
           let maxlen := if Z.ltb (ml) (bl) then bl else ml in
           let whole_words := e_div (maxlen) (8) in
           let words := Z.add (whole_words) ((if Z.eqb ((Z.rem (maxlen) (8))) (0) then 0 else 1)) in
           let product_limit_value : Z :=
             if osaka then available
             else Z.add ((Z.mul (3) (available))) (2) in
           let product_limit := product_limit_value in
           let words_unaffordable := Z.ltb (product_limit) (words) in
           let bounded_words : Z := if words_unaffordable then product_limit else words in
           (if words_unaffordable then returnR (GasCharge) (GAS_CHARGE_UNAFFORDABLE)
            else
              let words_squared : Z := Z.mul (bounded_words) (bounded_words) in
              let wide_product_limit : Z := product_limit in
              let square_unaffordable := Z.ltb (wide_product_limit) (words_squared) in
              let affordable_square : Z :=
                if square_unaffordable then product_limit
                else words_squared in
              (if square_unaffordable then returnR (GasCharge) (GAS_CHARGE_UNAFFORDABLE)
               else
                 (if andb (osaka) ((Z.leb (maxlen) (32))) then returnR (GasCharge) (16)
                  else if osaka return MR (GasCharge) (Z) then
                    let doubled_limit_value : Z := e_div (available) (2) in
                    let doubled_limit := doubled_limit_value in
                    let wide_doubled_limit : Z := doubled_limit in
                    let doubled_unaffordable := Z.gtb (words_squared) (wide_doubled_limit) in
                    let bounded_square : Z := if doubled_unaffordable then 0 else words_squared in
                    (if doubled_unaffordable return MR (GasCharge) (Z) then
                       (early_return (GAS_CHARGE_UNAFFORDABLE  : GasCharge) : MR GasCharge Z)
                        : MR (GasCharge) (Z)
                     else returnR (GasCharge) ((Z.mul (2) (bounded_square))))
                     : MR (GasCharge) (Z)
                  else returnR (GasCharge) (affordable_square)) >>= fun (mult_value : Z) =>
                 let mult := mult_value in
                 (if Z.ltb (product_limit) (mult) then returnR (GasCharge) (GAS_CHARGE_UNAFFORDABLE)
                  else
                    (if Z.leb (el) (32) return MR (GasCharge) (Z) then
                       liftR (((pc_word_after_declared_field (input) (96) (Build_word ((bl))) (el)) >>= fun semanticResult =>
                               returnM (semanticResult).(word_value))) >>= fun (w__3 : Z) =>
                       let exponent_bits := (word_bit_length (w__3)).(word_bit_count_value) in
                       returnR (GasCharge) ((if Z.eqb (exponent_bits) (0) then 1
                                             else
                                               let count := Z.sub (exponent_bits) (1) in
                                               if Z.eqb (count) (0) then 1
                                               else count))
                     else
                       liftR (((pc_word_after_declared_field (input) (96) (Build_word ((bl))) (32)) >>= fun semanticResult =>
                               returnM (semanticResult).(word_value))) >>= fun (w__4 : Z) =>
                       let head_bits := (word_bit_length (w__4)).(word_bit_count_value) in
                       let high_bits := if neq_int (head_bits) (0) then Z.sub (head_bits) (1) else 0 in
                       let extra := Z.sub (el) (32) in
                       (if osaka return MR (GasCharge) (Z) then
                          let extra_limit : Z := e_div (available) (16) in
                          let osaka_extra : Z :=
                            if word_greater_than_word (extra) (((u256 (992)).(word_value))) then 992
                            else extra in
                          let extra_unaffordable := Z.gtb (osaka_extra) (extra_limit) in
                          let bounded_extra : Z :=
                            if extra_unaffordable then extra_limit
                            else osaka_extra in
                          (if extra_unaffordable return MR (GasCharge) (Z) then
                             (early_return (GAS_CHARGE_UNAFFORDABLE  : GasCharge) : MR GasCharge Z)
                              : MR (GasCharge) (Z)
                           else
                             returnR (GasCharge) ((Z.add ((Z.mul (16) (bounded_extra))) (high_bits))))
                           : MR (GasCharge) (Z)
                        else
                          let pre_osaka_limit := Z.add ((Z.mul (3) (available))) (2) in
                          let extra_limit : Z := e_div (pre_osaka_limit) (8) in
                          let extra_unaffordable := Z.gtb (extra) (extra_limit) in
                          let bounded_extra : Z := if extra_unaffordable then extra_limit else extra in
                          (if extra_unaffordable return MR (GasCharge) (Z) then
                             (early_return (GAS_CHARGE_UNAFFORDABLE  : GasCharge) : MR GasCharge Z)
                              : MR (GasCharge) (Z)
                           else
                             returnR (GasCharge) ((Z.add ((Z.mul (8) (bounded_extra))) (high_bits))))
                           : MR (GasCharge) (Z)) >>= fun (count : Z) =>
                       returnR (GasCharge) ((if Z.eqb (count) (0) then 1 else count))) >>= fun (iterations : Z) =>
                    returnR (GasCharge) ((if Z.eqb (iterations) (0) then GAS_CHARGE_UNAFFORDABLE
                                          else
                                            let product : Z := Z.mul (mult) (iterations) in
                                            let product_unaffordable :=
                                              Z.ltb (wide_product_limit) (product) in
                                            let affordable_product : Z :=
                                              if product_unaffordable then product_limit
                                              else product in
                                            if product_unaffordable then GAS_CHARGE_UNAFFORDABLE
                                            else
                                              let calculated :=
                                                if osaka then affordable_product
                                                else e_div (affordable_product) (3) in
                                              let cost :=
                                                if Z.ltb (calculated) (minimum) then minimum
                                                else calculated in
                                              if Z.leb (cost) (available) then
                                                let affordable : Z := cost in
                                                gas_charge (affordable)
                                              else GAS_CHARGE_UNAFFORDABLE)))
                  : MR (GasCharge) (GasCharge))
               : MR (GasCharge) (GasCharge))
            : MR (GasCharge) (GasCharge))
         : MR (GasCharge) (GasCharge))
      : MR (GasCharge) (GasCharge)).

