Definition bls_msm_gas
(table : vec bls_discount 128) (base : gas_constant) (maxd : bls_discount) (k : source_length)
(available : Z) (*(0 <=? base) && (base <=? 45000)*) (*(0 <=? maxd) && (maxd <=? (2 ^ 16 - 1))*)
(*(0 <=? k) && (k <=? (2 ^ 32 - 1))*) (*0 <=? available*)
: GasCharge :=
   let table := (vec_map (fun semanticValue => (semanticValue).(bls_discount_value)) (table)) in
   let base := (base).(gas_constant_value) in
   let maxd := (maxd).(bls_discount_value) in
   let k := (k).(source_length_value) in
   if Z.eqb (k) (0) then gas_charge (GAS_COST_ZERO)
   else
     let discount : Z := maxd in
     let discount : Z :=
       if Z.ltb (k) (128) then
         let index : Z := Z.sub (128) (k) in
         vec_access_dec (table) (index)
       else discount in
     let coefficient : Z := Z.mul (base) (discount) in
     let whole := e_div (k) (1000) in
     let remainder := Z.rem (k) (1000) in
     let whole_product : Z := Z.mul (coefficient) (whole) in
     if Z.gtb (whole_product) (available) then GAS_CHARGE_UNAFFORDABLE
     else
       let major : Z := whole_product in
       let tail_product : Z := Z.mul (coefficient) (remainder) in
       let tail : Z := e_div (tail_product) (1000) in
       let total : Z := Z.add (major) (tail) in
       if Z.leb (total) (available) then
         let affordable : Z := total in
         gas_charge (affordable)
       else GAS_CHARGE_UNAFFORDABLE.

Definition linear_gas
(base : gas_constant) (per_unit : gas_constant) (units : source_length) (available : Z)
(*(0 <=? base) && (base <=? 45000)*) (*(0 <=? per_unit) && (per_unit <=? 45000)*)
(*(0 <=? units) && (units <=? (2 ^ 32 - 1))*) (*0 <=? available*)
: GasCharge :=
   let base := (base).(gas_constant_value) in
   let per_unit := (per_unit).(gas_constant_value) in
   let units := (units).(source_length_value) in
   let variable_cost : Z := Z.mul (per_unit) (units) in
   let exact_cost : Z := Z.add (variable_cost) (base) in
   if Z.gtb (exact_cost) (available) then GAS_CHARGE_UNAFFORDABLE
   else
     let affordable : Z := exact_cost in
     gas_charge (affordable).

Definition fixed_precompile_gas (cost : Z) (available : Z) (*0 <=? cost*) (*0 <=? available*)
: GasCharge :=
   if Z.leb (cost) (available) then
     let affordable : Z := cost in
     gas_charge (affordable)
   else GAS_CHARGE_UNAFFORDABLE.

Definition precompile_gas (num : PrecompileId) (input : CalldataSlice) (available : Z)
(*0 <=? available*)
: M (GasCharge) :=
   let input_len := (calldata_slice_length (input)).(source_length_value) in
   let input_length := input_len in
   let words := memory_word_count (input_len) in
   match num with
   | NotPrecompile => returnM (GAS_CHARGE_UNAFFORDABLE)
   | Ecrecover => returnM ((fixed_precompile_gas (3000) (available)))
   | Sha256 =>
      returnM ((linear_gas (Build_gas_constant ((60))) (Build_gas_constant ((12)))
                  (Build_source_length ((words))) (available)))
   | Ripemd160 =>
      returnM ((linear_gas (Build_gas_constant ((600))) (Build_gas_constant ((120)))
                  (Build_source_length ((words))) (available)))
   | Identity =>
      returnM ((linear_gas (Build_gas_constant ((15))) (Build_gas_constant ((3)))
                  (Build_source_length ((words))) (available)))
   | Modexp => (modexp_gas (input) (available))  : M (GasCharge)
   | Bn254Add => returnM ((fixed_precompile_gas (150) (available)))
   | Bn254Mul => returnM ((fixed_precompile_gas (6000) (available)))
   | Bn254Pairing =>
      returnM ((linear_gas (Build_gas_constant ((45000))) (Build_gas_constant ((34000)))
                  (Build_source_length (((e_div (input_length) (192))))) (available)))
   | Blake2f =>
      ((pc_blake2_rounds (input)) >>= fun semanticResult =>
       returnM (semanticResult).(blake2_rounds_value)) >>= fun (w__1 : Z) =>
      returnM ((fixed_precompile_gas (w__1) (available)))
   | KzgPointEvaluation => returnM ((fixed_precompile_gas (50000) (available)))
   | BlsG1Add => returnM ((fixed_precompile_gas (375) (available)))
   | BlsG1Msm =>
      returnM ((bls_msm_gas
                  (vec_map (fun semanticValue => (Build_bls_discount (semanticValue))) (((vec_map (fun semanticValue => (semanticValue).(bls_discount_value)) (BLS_G1_DISCOUNT)))))
                  (Build_gas_constant ((12000))) (Build_bls_discount ((519)))
                  (Build_source_length (((e_div (input_length) (160))))) (available)))
   | BlsG2Add => returnM ((fixed_precompile_gas (600) (available)))
   | BlsG2Msm =>
      returnM ((bls_msm_gas
                  (vec_map (fun semanticValue => (Build_bls_discount (semanticValue))) (((vec_map (fun semanticValue => (semanticValue).(bls_discount_value)) (BLS_G2_DISCOUNT)))))
                  (Build_gas_constant ((22500))) (Build_bls_discount ((524)))
                  (Build_source_length (((e_div (input_length) (288))))) (available)))
   | BlsPairing =>
      returnM ((linear_gas (Build_gas_constant ((37700))) (Build_gas_constant ((32600)))
                  (Build_source_length (((e_div (input_length) (384))))) (available)))
   | BlsMapFpToG1 => returnM ((fixed_precompile_gas (5500) (available)))
   | BlsMapFp2ToG2 => returnM ((fixed_precompile_gas (23800) (available)))
   | P256Verify => returnM ((fixed_precompile_gas (6900) (available)))
   end
    : M (GasCharge).

