   | EXTCODESIZE tt => returnM ((1, 1))
   | EXTCODECOPY tt => returnM ((4, 0))
   | RETURNDATASIZE tt => returnM ((0, 1))
   | RETURNDATACOPY tt => returnM ((3, 0))
   | EXTCODEHASH tt => returnM ((1, 1))
   | BLOCKHASH tt => returnM ((1, 1))
   | COINBASE tt => returnM ((0, 1))
