   | SELFBALANCE tt => returnM ((0, 1))
   | BASEFEE tt => returnM ((0, 1))
   | BLOBHASH tt => returnM ((1, 1))
   | BLOBBASEFEE tt => returnM ((0, 1))
   | SLOTNUM tt => returnM ((0, 1))
   | POP tt => returnM ((1, 0))
   | MLOAD tt => returnM ((1, 1))
   | MSTORE tt => returnM ((2, 0))
   | MSTORE8 tt => returnM ((2, 0))
   | SLOAD tt => returnM ((1, 1))
   | SSTORE tt => returnM ((2, 0))
   | JUMP tt => returnM ((1, 0))
   | JUMPI tt => returnM ((2, 0))
   | PC tt => returnM ((0, 1))
   | MSIZE tt => returnM ((0, 1))
   | GAS tt => returnM ((0, 1))
   | JUMPDEST tt => returnM ((0, 0))
   | TLOAD tt => returnM ((1, 1))
   | TSTORE tt => returnM ((2, 0))
